-- ============================================
-- LUMA — Enrichissement Thématique 1 (Restaurant) : scénarios longs beaucoup plus riches
-- ============================================

update scenarios set content = '{"characters": {"host": "M. Reynolds (client potentiel)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "host", "text": "Thank you for joining me tonight. Shall we start with drinks?", "text_fr": "Merci de m''avoir rejoint ce soir. On commence par les boissons ?", "choices": [{"text": "That sounds great, I''ll have a sparkling water.", "next": "n2a"}, {"text": "I''d love a glass of red wine, thank you.", "next": "n2b"}, {"text": "Actually, could we get straight to business? I have another meeting after.", "next": "n2c"}]}, "n2a": {"speaker": "host", "text": "Sensible choice, keeping a clear head. So, tell me about your company''s plans.", "text_fr": "Choix judicieux, garder les idées claires. Alors, parlez-moi des projets de votre entreprise.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3"}, {"text": "I''d rather hear about your priorities first.", "next": "n3b"}]}, "n2b": {"speaker": "host", "text": "A person who enjoys a good glass, I respect that. So, tell me about your plans.", "text_fr": "Une personne qui apprécie un bon verre, je respecte ça. Alors, parlez-moi de vos projets.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3"}, {"text": "I''d rather hear about your priorities first.", "next": "n3b"}]}, "n2c": {"speaker": "host", "text": "Direct — I like that. Very well, let''s not waste time.", "text_fr": "Direct — j''aime ça. Très bien, ne perdons pas de temps.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3fast"}]}, "n3": {"speaker": "host", "text": "Ambitious! What''s driving that decision?", "text_fr": "Ambitieux ! Qu''est-ce qui motive cette décision ?", "choices": [{"text": "Strong demand and a solid financial position.", "next": "n4"}, {"text": "Honestly, competitive pressure is forcing our hand.", "next": "n4b"}]}, "n3b": {"speaker": "host", "text": "Fair enough. Honestly, we''re looking for a reliable long-term partner.", "text_fr": "Entendu. Honnêtement, on cherche un partenaire fiable sur le long terme.", "choices": [{"text": "That aligns well with what we''re looking for too.", "next": "n4"}]}, "n3fast": {"speaker": "host", "text": "Good, straight answers. Let''s talk numbers immediately then.", "text_fr": "Bien, des réponses directes. Parlons chiffres tout de suite alors.", "choices": [{"text": "We can discuss volume discounts for a multi-year deal.", "next": "n6"}]}, "n4": {"speaker": "host", "text": "I like that. Shall we order? I recommend the sea bass.", "text_fr": "J''aime ça. On commande ? Je recommande le bar de mer.", "choices": [{"text": "I''ll trust your recommendation, thank you.", "next": "n5"}, {"text": "I think I''ll go with the steak, if that''s fine.", "next": "n5"}]}, "n4b": {"speaker": "host", "text": "Honesty about competitive pressure — that''s rare in these meetings.", "text_fr": "L''honnêteté sur la pression concurrentielle — c''est rare dans ce genre de réunion.", "choices": [{"text": "I believe transparency builds better partnerships.", "next": "n5"}]}, "n5": {"speaker": "host", "text": "Good choice. Now, about pricing — what flexibility do you have?", "text_fr": "Bon choix. Maintenant, côté tarifs — quelle flexibilité avez-vous ?", "choices": [{"text": "We can discuss volume discounts for a multi-year deal.", "next": "n6"}, {"text": "Let''s finalize the partnership first, then discuss numbers.", "next": "n6b"}, {"text": "I''d need to check with my team before committing to specifics.", "next": "n6c"}]}, "n6": {"speaker": "host", "text": "That''s exactly the kind of flexibility we need. But I have a concern — your delivery timelines.", "text_fr": "C''est exactement la flexibilité dont on a besoin. Mais j''ai une préoccupation — vos délais de livraison.", "choices": [{"text": "We can guarantee priority handling for your account.", "next": "n7"}, {"text": "Let me be honest — there could be occasional delays during peak season.", "next": "n7b"}]}, "n6b": {"speaker": "host", "text": "I appreciate that approach. But my board will want numbers eventually.", "text_fr": "J''apprécie cette approche. Mais mon conseil voudra des chiffres à un moment.", "choices": [{"text": "Understood, I''ll have a full proposal ready within the week.", "next": "n7"}]}, "n6c": {"speaker": "host", "text": "Reasonable, though I do value decisiveness in a partner.", "text_fr": "Raisonnable, même si j''apprécie la capacité de décision chez un partenaire.", "choices": [{"text": "I can give you a provisional range tonight, and confirm formally this week.", "next": "n7"}]}, "n7": {"speaker": "host", "text": "Good. Last thing — I''ll need this finalized before the end of the month.", "text_fr": "Bien. Dernière chose — j''aurai besoin que ce soit finalisé avant la fin du mois.", "choices": [{"text": "That''s tight, but we can make it work.", "next": "end_deal"}, {"text": "That''s ambitious — let''s aim for it but stay realistic.", "next": "end_realistic"}]}, "n7b": {"speaker": "host", "text": "I appreciate the honesty more than empty promises.", "text_fr": "J''apprécie l''honnêteté plus que des promesses vides.", "choices": [{"text": "Trust matters more to me than overselling.", "next": "end_honest"}]}, "end_deal": {"speaker": "host", "text": "Looking forward to it. This could be the start of something great.", "text_fr": "J''ai hâte. Ça pourrait être le début de quelque chose de formidable.", "end": true, "ending_label": "Partenariat scellé rapidement 🤝"}, "end_realistic": {"speaker": "host", "text": "I respect that you''re not overpromising. Let''s aim for it together.", "text_fr": "Je respecte que vous ne promettiez pas plus que possible. Visons ça ensemble.", "end": true, "ending_label": "Partenariat réaliste et solide 🤝"}, "end_honest": {"speaker": "host", "text": "This is exactly the kind of partner I want — honest, even when it''s inconvenient.", "text_fr": "C''est exactement le genre de partenaire que je veux — honnête, même quand c''est inconfortable.", "end": true, "ending_label": "Confiance gagnée par l''honnêteté 💎"}}}'::jsonb, is_playable = true
where title = 'Un dîner d''affaires à enjeux'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"waiter": "le serveur", "friend": "ton ami Sam"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "I''m so sorry, I think I just knocked over your glass!", "text_fr": "Je suis désolé, je crois que je viens de renverser ton verre !", "choices": [{"text": "Don''t worry, it happens! Let''s ask for a napkin.", "next": "n2"}, {"text": "Oh no, my phone got wet too!", "next": "n2b"}, {"text": "(stay calm, but you''re actually a bit annoyed)", "next": "n2c"}]}, "n2": {"speaker": "waiter", "text": "No worries at all, let me clean this up quickly.", "text_fr": "Aucun souci, je nettoie ça tout de suite.", "choices": [{"text": "Thank you, we appreciate it.", "next": "n3"}]}, "n2b": {"speaker": "waiter", "text": "I''m so sorry! Let me bring some towels right away.", "text_fr": "Je suis vraiment désolé ! J''apporte des serviettes tout de suite.", "choices": [{"text": "Thanks, hopefully it still works.", "next": "n3b"}]}, "n2c": {"speaker": "friend", "text": "You seem a bit upset — I really am sorry about this.", "text_fr": "Tu sembles un peu contrarié — je suis vraiment désolé pour ça.", "choices": [{"text": "I''m fine, just startled, don''t worry about it.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Would you like a replacement drink, on the house?", "text_fr": "Vous voulez une boisson de remplacement, offerte par la maison ?", "choices": [{"text": "That''s very kind, yes please.", "next": "n4"}, {"text": "That''s not necessary, but thank you.", "next": "n4b"}]}, "n3b": {"speaker": "waiter", "text": "Let me check if the phone still works while I get you a towel.", "text_fr": "Laissez-moi vérifier si le téléphone fonctionne encore pendant que j''apporte une serviette.", "choices": [{"text": "Thanks, fingers crossed it''s okay.", "next": "n4c"}]}, "n4": {"speaker": "friend", "text": "See, it turned out fine in the end!", "text_fr": "Tu vois, finalement tout s''est bien passé !", "choices": [{"text": "Yeah, and free drinks too!", "next": "n5"}]}, "n4b": {"speaker": "friend", "text": "You''re very understanding, thanks for not making a big deal of it.", "text_fr": "Tu es très compréhensif, merci de ne pas en avoir fait tout un plat.", "choices": [{"text": "No worries, these things happen!", "next": "n5"}]}, "n4c": {"speaker": "waiter", "text": "Good news, it still turns on, just a bit wet.", "text_fr": "Bonne nouvelle, il s''allume encore, juste un peu mouillé.", "choices": [{"text": "What a relief, thank you for checking.", "next": "n5"}]}, "n5": {"speaker": "friend", "text": "I feel like I should make it up to you somehow — dessert''s on me?", "text_fr": "J''ai l''impression que je devrais me rattraper d''une façon — le dessert, c''est pour moi ?", "choices": [{"text": "You really don''t have to, but I won''t say no to dessert!", "next": "end_positive"}, {"text": "That''s sweet, but honestly the evening''s already saved.", "next": "end_gracious"}]}, "end_positive": {"speaker": "waiter", "text": "Thank you both for being so kind about it. I''ll bring the dessert menu.", "text_fr": "Merci à vous deux d''être aussi compréhensifs. Je vous apporte la carte des desserts.", "end": true, "ending_label": "Incident géré avec le sourire, et un dessert en prime 🍰"}, "end_gracious": {"speaker": "waiter", "text": "That''s very generous of you both. Enjoy the rest of your evening!", "text_fr": "C''est très généreux de votre part à tous les deux. Bonne fin de soirée !", "end": true, "ending_label": "Incident géré avec élégance 😊"}}}'::jsonb, is_playable = true
where title = 'Une soirée qui tourne mal'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"partner": "ton/ta partenaire", "waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "This restaurant is beautiful, I can''t believe you planned all this.", "text_fr": "Ce restaurant est magnifique, je n''arrive pas à croire que tu aies tout organisé.", "choices": [{"text": "I wanted tonight to be really special.", "next": "n2"}, {"text": "I have something important to ask you tonight.", "next": "n2b"}, {"text": "(stay mysterious and just smile)", "next": "n2c"}]}, "n2": {"speaker": "waiter", "text": "Good evening, would you like to start with some champagne?", "text_fr": "Bonsoir, vous souhaitez commencer par du champagne ?", "choices": [{"text": "Yes, please, we''re celebrating something special.", "next": "n3"}]}, "n2b": {"speaker": "partner", "text": "You''re making me nervous, in a good way!", "text_fr": "Tu me rends nerveux/nerveuse, mais dans le bon sens !", "choices": [{"text": "Just wait until dessert.", "next": "n3"}]}, "n2c": {"speaker": "partner", "text": "That smile is telling me something''s up... a good something?", "text_fr": "Ce sourire me dit qu''il se passe quelque chose... quelque chose de bien ?", "choices": [{"text": "You''ll just have to wait and see.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Wonderful, I''ll bring a bottle right away.", "text_fr": "Merveilleux, j''apporte une bouteille tout de suite.", "choices": [{"text": "Thank you so much.", "next": "n4"}]}, "n4": {"speaker": "partner", "text": "Okay, now I''m really curious what you''re planning. Talk to me!", "text_fr": "Bon, maintenant je suis vraiment curieux/curieuse de savoir ce que tu prépares. Dis-moi tout !", "choices": [{"text": "Let''s just enjoy dinner first, I promise it''s worth the wait.", "next": "n5"}, {"text": "(nervously drop your fork, feeling the pressure of the moment)", "next": "n5b"}]}, "n5": {"speaker": "partner", "text": "Fine, but you''re killing me with the suspense!", "text_fr": "D''accord, mais tu me tues avec ce suspense !", "choices": [{"text": "(the meal continues, dessert arrives)", "next": "n6"}]}, "n5b": {"speaker": "partner", "text": "Are you okay? You seem really nervous tonight.", "text_fr": "Ça va ? Tu sembles vraiment nerveux/nerveuse ce soir.", "choices": [{"text": "I am, actually — there''s something big I want to ask you.", "next": "n6"}]}, "n6": {"speaker": "partner", "text": "Okay, now I need to know. What is it?", "text_fr": "Bon, maintenant j''ai besoin de savoir. C''est quoi ?", "choices": [{"text": "(Take out the ring) Will you marry me?", "next": "n7"}]}, "n7": {"speaker": "partner", "text": "(stunned silence, then tears) Yes! Yes, of course!", "text_fr": "(silence stupéfait, puis des larmes) Oui ! Oui, bien sûr !", "choices": [{"text": "You''ve just made me the happiest person alive.", "next": "end_yes"}, {"text": "I''ve been waiting so long for the right moment to ask.", "next": "end_relief"}]}, "end_yes": {"speaker": "waiter", "text": "Congratulations to you both! The champagne is on us tonight.", "text_fr": "Félicitations à vous deux ! Le champagne est offert ce soir.", "end": true, "ending_label": "Elle/il a dit oui ! 💍"}, "end_relief": {"speaker": "waiter", "text": "What a beautiful moment to witness — congratulations!", "text_fr": "Quel beau moment d''assister à ça — félicitations !", "end": true, "ending_label": "Soulagement et bonheur partagés 💍💕"}}}'::jsonb, is_playable = true
where title = 'Un repas de fiançailles'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
